 async Task ResidentialCoopChecks(CoopActor a){string old=Json.Write(a.Game.Craft);var stripped=game.World.Changes.StrippedFurniture.ToList();int hostScrap=game.Craft.ScrapMetal;try{ClearEnemies();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);var f=props.First(p=>p.Kind==42&&p.Id=="briar/BriarLaneHouse0/furniture/0");a.Body.Position=f.Position+new Vector3(0,0,2);a.Game.Craft.HasAxe=true;a.Game.Stamina=a.Game.MaxStamina;a.Game.Shield=30;int before=a.Game.Craft.ScrapMetal;residentialCoopAck=false;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));RpcId(a.Id,nameof(CoopCheckStage),"residential-salvage",a.Body.Position);await CoopWait(()=>residentialCoopAck,"Guest furniture salvage did not finish",20);MigrationChecks.Assert(game.World.Changes.StrippedFurniture.Contains(f.Id)&&a.Game.Craft.ScrapMetal==before+1&&game.Craft.ScrapMetal==hostScrap,"Host furniture reward is private and conserved");int final=a.Game.Craft.ScrapMetal;WithCoopActor(a,()=>SalvageFurnitureAction(f.Id));MigrationChecks.Assert(a.Game.Craft.ScrapMetal==final,"Destroyed furniture cannot be awarded twice");GD.Print("PASS / two-process furniture: physical guest aim, timed strikes, shared disappearance, private scrap, saved world state and duplicate rejection");}finally{a.Game.Profile.Crafting=Json.Read<ExpeditionCraftState>(old);game.World.Changes.StrippedFurniture=stripped;ClearEnemies();Teleport(0,12);a.Body.Position=HostPosition+Vector3.Right*3;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"Furniture checks complete",a.Body.Position,true);}}
 async Task ClientResidentialChecks(Vector3 target){await CoopWait(()=>Distance(player.Position,target)<.2f&&game.Craft.HasAxe,"Furniture test profile missing");StreamTerrain(true);await CoopWait(()=>props.Any(p=>p.Id=="briar/BriarLaneHouse0/furniture/0"),"Physical furniture replica missing");var f=props.First(p=>p.Id=="briar/BriarLaneHouse0/furniture/0");int scrap=game.Craft.ScrapMetal;player.Rotation=Vector3.Zero;camera.LookAt(f.Position);var rot=camera.Rotation;player.Rotation=new(0,rot.Y,0);pitch=rot.X;camera.Rotation=new(pitch,0,0);await CoopDelay(.4);MigrationChecks.Assert(AimedFurniture()==f,"Guest aims at actual furniture collider");for(int i=0;i<3;i++){CoopRequest("furniture",f.Id);await CoopDelay(.85);}await CoopWait(()=>game.World.Changes.StrippedFurniture.Contains(f.Id)&&game.Craft.ScrapMetal==scrap+1&&!props.Any(p=>p.Id==f.Id),"Furniture world state, scrap or replica removal missing");RpcId(1,nameof(CoopResidentialAck));}
